    """Turn background gaps to color 2 on a row/column containing >=3 markers."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = min((value for value in counts if value != background), key=lambda value: counts[value])
    out = [row[:] for row in grid]

    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        if len(positions) >= 3:
            for left, right in zip(positions, positions[1:]):
                for c in range(left + 1, right):
                    if grid[r][c] == background:
                        out[r][c] = 2

